// Simple Space Survivor game
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas with id "game" not found.');
    return;
  }
  const ctx = canvas.getContext('2d');
  // Set canvas size to fill its container or use defined size
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  // ----- Ship -----
  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    r: 12, // radius for collision
    angle: 0, // radians
    vx: 0,
    vy: 0,
    thrust: 0.1,
    rotateSpeed: 0.07,
    color: 'white',
  };

  // ----- Asteroids -----
  const asteroids = [];
  const asteroidSpawnInterval = 1500; // ms
  const maxAsteroidSize = 30;
  const minAsteroidSize = 10;
  let lastSpawn = 0;

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', (e) => (keys[e.code] = true));
  window.addEventListener('keyup', (e) => (keys[e.code] = false));

  // ----- Game state -----
  let score = 0;
  let gameOver = false;

  function update(dt) {
    if (gameOver) return;

    // Ship rotation
    if (keys['ArrowLeft']) ship.angle -= ship.rotateSpeed;
    if (keys['ArrowRight']) ship.angle += ship.rotateSpeed;
    // Ship thrust
    if (keys['ArrowUp']) {
      ship.vx += Math.cos(ship.angle) * ship.thrust;
      ship.vy += Math.sin(ship.angle) * ship.thrust;
    }
    // Apply velocity
    ship.x += ship.vx;
    ship.y += ship.vy;
    // Simple friction
    ship.vx *= 0.99;
    ship.vy *= 0.99;

    // Boundary check – losing condition if leaves canvas
    if (
      ship.x < 0 || ship.x > canvas.width ||
      ship.y < 0 || ship.y > canvas.height
    ) {
      gameOver = true;
    }

    // Spawn asteroids
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx;
      a.y += a.vy;
      // Remove when off-screen
      if (
        a.x < -a.r || a.x > canvas.width + a.r ||
        a.y < -a.r || a.y > canvas.height + a.r
      ) {
        asteroids.splice(i, 1);
        score++; // survived an asteroid
        continue;
      }
      // Collision with ship
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.r) {
        gameOver = true;
        break;
      }
    }
  }

  function spawnAsteroid() {
    const r = Math.random() * (maxAsteroidSize - minAsteroidSize) + minAsteroidSize;
    // Random edge
    const edge = Math.floor(Math.random() * 4);
    let x, y, vx, vy;
    const speed = Math.random() * 1.5 + 0.5;
    switch (edge) {
      case 0: // top
        x = Math.random() * canvas.width;
        y = -r;
        vx = (Math.random() - 0.5) * speed;
        vy = speed;
        break;
      case 1: // right
        x = canvas.width + r;
        y = Math.random() * canvas.height;
        vx = -speed;
        vy = (Math.random() - 0.5) * speed;
        break;
      case 2: // bottom
        x = Math.random() * canvas.width;
        y = canvas.height + r;
        vx = (Math.random() - 0.5) * speed;
        vy = -speed;
        break;
      case 3: // left
        x = -r;
        y = Math.random() * canvas.height;
        vx = speed;
        vy = (Math.random() - 0.5) * speed;
        break;
    }
    asteroids.push({ x, y, vx, vy, r, color: 'gray' });
  }

  function draw() {
    // Clear
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = ship.color;
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Asteroids
    for (const a of asteroids) {
      ctx.fillStyle = a.color;
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // UI
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (gameOver) {
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
